  __m512d v17 = v5 + v9;
  __m512d v18 = v1 + v17;
  __m512d v19 = v3 + v11;
  __m512d v20 = v7 + v19;
  __m512d v21 = v18 + v20;
  _mm512_storeu_pd(pyi + 0*sy, v21);
  __m512d v22 = _mm512_set1_pd(-0x1.ffffffffffffdp-2) * v12;
  __m512d v23 = v0 + v22;
  __m512d v24 = v5 - v9;
  __m512d v25 = _mm512_set1_pd(0x1.bb67ae8584cabp-1) * v24;
