  __m512d v34 = v1 + v33;
  __m512d v35 = v4 - v8;
  __m512d v36 = _mm512_set1_pd(0x1.bb67ae8584cabp-1) * v35;
  __m512d v37 = v34 - v36;
  __m512d v38 = _mm512_set1_pd(-0x1.ffffffffffffdp-2) * v19;
  __m512d v39 = v7 + v38;
  __m512d v40 = v10 - v2;
  __m512d v41 = _mm512_set1_pd(0x1.bb67ae8584cabp-1) * v40;
  __m512d v42 = v39 - v41;
  __m512d v43 = v37 - v42;
  _mm512_storeu_pd(pyi + 1*sy, v43);
  __m512d v44 = v23 - v25;
  __m512d v45 = v28 - v30;
  __m512d v46 = v44 + v45;
  _mm512_storeu_pd(pyr + 2*sy, v46);
  __m512d v47 = v34 + v36;
  __m512d v48 = v39 + v41;
  __m512d v49 = v47 + v48;
  _mm512_storeu_pd(pyi + 2*sy, v49);
  __m512d v50 = v13 - v15;
  _mm512_storeu_pd(pyr + 3*sy, v50);
  __m512d v51 = v18 - v20;
  _mm512_storeu_pd(pyi + 3*sy, v51);
