  __m512d v15 = _mm512_loadu_pd(pxi + 7*sx);
  __m512d v16 = v0 + v8;
  __m512d v17 = v4 + v12;
  __m512d v18 = v16 + v17;
  __m512d v19 = v2 + v10;
  __m512d v20 = v6 + v14;
  __m512d v21 = v19 + v20;
